package com.example.starter.domain;

/**
 * 靠泊申请状态。
 */
public enum AllocationStatus {

    /** 已确认，占用泊位区间。 */
    CONFIRMED,

    /** 潮高修订后深度不再满足，待人工复核；已释放泊位占用。 */
    PENDING_REVIEW,

    /** 已拒绝（深度不足、窗口冲突、复核驳回等），不占泊位。 */
    REJECTED
}

package com.example.starter.domain;

/**
 * 拒绝或挂起原因代码，供调用方区分失败分支。
 */
public final class RejectReason {

    /** 申请区间内潮高区间存在缺口，无法完成校核。 */
    public static final String TIDE_GAP = "TIDE_GAP";

    /** 泊位静态水深加最低潮高后仍小于吃水加安全余量。 */
    public static final String DEPTH_INSUFFICIENT = "DEPTH_INSUFFICIENT";

    /** 同一泊位已有已确认靠泊区间与申请区间重叠。 */
    public static final String BERTH_CONFLICT = "BERTH_CONFLICT";

    /** 人工复核驳回。 */
    public static final String REVIEW_REJECTED = "REVIEW_REJECTED";

    private RejectReason() {
    }
}

package com.example.starter.domain;

import java.math.BigDecimal;

/**
 * 泊位静态信息。
 *
 * @param id           泊位主键
 * @param code         泊位编码，对外使用
 * @param name         泊位名称
 * @param staticDepthM 泊位静态水深，单位米（相对同一潮高基准面）
 */
public record Berth(Long id, String code, String name, BigDecimal staticDepthM) {
}

package com.example.starter.domain;

import java.time.LocalDateTime;

/**
 * 潮高版本（一次潮汐表修订发布）。
 *
 * @param id          主键
 * @param versionNo   版本号，从 1 递增，唯一
 * @param publishedAt 发布时间，业务时区 Asia/Shanghai
 * @param remark      备注，可为空
 */
public record TideVersion(Long id, Integer versionNo, LocalDateTime publishedAt, String remark) {
}

