    // ---------- 422 失败分支 ----------

    @Test
    void returns422ForNonPositiveInterval() throws Exception {
        Map<String, Object> body = applyBody("req-bad-interval", "合成船", "9.20", "0.20", T08, T08);

        mockMvc.perform(post(APPLY_URL).contentType("application/json")
